mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.TRADE_MARKET tradeMarket, T1.ENTRUST_NUM * 100 purchBondTotal, T1.CCY ccy, T1.REMARK remark, T1.INV_AIM invAim, T7.ASSET_TYPE1 assetType1, T1.ENTRUST_DATE entrustDate, T7.PURCH_MODLE purchModle, T7.PURCH_TYPE purchType, TT.PRIN_AMT winlotteryAmt FROM ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T11 ON T11.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T11.USER_ID = #{userId} LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = T3.FINPROD_ID
LEFT JOIN (select T5.ENTRUST_ID,T6.PRIN_AMT from TRD_PRODUCT_DEAL_ADD T5 LEFT JOIN TRD_PRODUCT_DEAL T6 ON T5.TRADE_ID = T6.TRADE_ID AND T6.ps = #{PS_T05} where T6.PRIN_AMT is not null and t6.p_trade_id is null and t6.is_cancel= #{YES_OR_NO_N} )TT on T1.ENTRUST_ID = TT.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME
AND T3.FINPROD_TYPE2 =#{bond} AND (T4.TYPE_6 = #{type6_B14} OR T4.TYPE_6 = #{type6_B15}) and T1.ps = #{PS_T04}
AND ((T1.PORTFOLIO_ID IN
null) or T1.PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
) OR (T2.PARENT_PORTFOLIO_ID IN
null) or T2.PARENT_PORTFOLIO_ID in (
#{prot,jdbcType=VARCHAR}
) )
AND (T3.FINPROD_ID like concat('%',concat(#{finprodId},'%')) or T3.FINPROD_ABBR like concat('%',concat(#{finprodId},'%')))
AND T1.TRADE_MARKET=#{tradeMarket}
AND T7.PURCH_MODLE=#{purchModle}
AND T7.PURCH_TYPE=#{purchType}
AND T1.ENTRUST_DATE >=STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.ENTRUST_DATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.ENTRUST_STATUS = #{entrustStatus}
order by T1.ENTRUST_ID DESC
